function EditReceivedDialog({action,call,token,close,done}){
 const d=action.document,[busy,setBusy]=useState(false),[dirty,setDirty]=useState(false),[error,setError]=useState(''),[originalUrl,setOriginalUrl]=useState(''),[replacementUrl,setReplacementUrl]=useState(''),[loading,setLoading]=useState(!!d.file_name);
 useEffect(()=>{if(!d.file_name){setLoading(false);return}let url='',controller=new AbortController();fetch(`${API}/documents/${d.id}/file`,{headers:{Authorization:`Bearer ${token}`},signal:controller.signal}).then(r=>{if(!r.ok)throw Error('Không thể tải file hiện tại');return r.blob()}).then(b=>{url=URL.createObjectURL(b);setOriginalUrl(url)}).catch(e=>{if(e.name!=='AbortError')setError(e.message)}).finally(()=>setLoading(false));return()=>{controller.abort();if(url)URL.revokeObjectURL(url)}},[d.id,d.file_name,token]);
 useEffect(()=>()=>{if(replacementUrl)URL.revokeObjectURL(replacementUrl)},[replacementUrl]);
 function previewReplacement(e){let f=e.target.files[0];setReplacementUrl(f?URL.createObjectURL(f):'');setDirty(true)}
 async function submit(e){e.preventDefault();setBusy(true);setError('');try{let body=new FormData(e.currentTarget);body.set('doc_type','CÔNG VĂN');await call(`/documents/${d.id}/edit-received`,{method:'POST',body});done()}catch(e){setError(e.message)}finally{setBusy(false)}}
 let previewUrl=replacementUrl||originalUrl;
 return <div className="modal action-modal edit-document-modal"><form onSubmit={submit} onChange={()=>setDirty(true)}><h2>Sửa công văn đến</h2><p>Tên file PDF được tạo tự động từ số ký hiệu và trích yếu.</p><div className="edit-document-layout"><div className="grid"><label>Loại văn bản<input value="CÔNG VĂN ĐẾN" disabled/></label><label>Ngày ban hành <span className="req">*</span><input name="issued_date" type="date" defaultValue={d.issued_date||''} required/></label><label className="wide">Trích yếu <span className="req">*</span><input name="title" defaultValue={d.title} required autoFocus/></label><label className="wide">Đơn vị ban hành <span className="req">*</span><input name="issuing_agency" defaultValue={d.issuing_agency||''} required/></label><label className="wide">Tóm tắt <small>(không bắt buộc)</small><textarea name="summary" defaultValue={d.summary||''}/></label><label className="wide">Thay file PDF (không bắt buộc vì đã có file)<input name="file" type="file" accept=".pdf,application/pdf" onChange={previewReplacement}/></label></div><section className="edit-file-preview"><b>{replacementUrl?'Xem trước PDF thay thế':'File hiện tại'}: {d.file_name||'Chưa có file'}</b>{loading&&!replacementUrl?<div className="preview-empty">Đang tải file...</div>:previewUrl?<object data={`${previewUrl}#toolbar=1`} type="application/pdf"><a href={previewUrl} target="_blank" rel="noreferrer">Mở file để kiểm tra</a></object>:<div className="preview-empty">Văn bản chưa có PDF để xem trước</div>}</section></div>{error&&<div className="form-error">{error}</div>}<div className="end"><button type="button" onClick={close} disabled={busy}>Hủy</button><button className="primary" disabled={busy||!dirty}>{busy?'Đang lưu...':'Lưu thay đổi'}</button></div></form></div>
}
function ReserveNumber({direction,token,close,saved}){const[busy,setBusy]=useState(false),[error,setError]=useState(''),internal=direction==='INTERNAL',incoming=direction==='IN';async function submit(e){e.preventDefault();setBusy(true);setError('');try{let endpoint=incoming?'/incoming/reserve-number':'/reserve-number',f=new FormData(e.currentTarget);if(!incoming)f.set('direction',direction);let r=await fetch(API+endpoint,{method:'POST',headers:{Authorization:`Bearer ${token}`},body:f}),j=await r.json();if(!r.ok)throw Error(j.detail||'Không thể xin số');saved(j)}catch(e){setError(e.message)}finally{setBusy(false)}}return <div className="modal action-modal"><form onSubmit={submit}><h2>Xin số {incoming?'công văn đến':direction==='OUT'?'công văn đi':'văn bản nội bộ'} trước</h2><div className="grid"><label>Loại văn bản {internal?<select name="doc_type" required><option value="">-- Chọn loại --</option><option>QUYẾT ĐỊNH</option><option>KẾ HOẠCH</option><option>THÔNG BÁO</option></select>:<><input value={incoming?'CÔNG VĂN ĐẾN':'CÔNG VĂN ĐI'} disabled/><input name="doc_type" type="hidden" value="CÔNG VĂN"/></>}</label>{incoming&&<label>Năm<input name="year" type="number" defaultValue={new Date().getFullYear()} required/></label>}<label className="wide">Trích yếu dự kiến <span className="req">*</span><input name="title" required/></label><label className="wide">{incoming?'Đơn vị ban hành dự kiến':direction==='OUT'?'Đơn vị tiếp nhận dự kiến':'Đơn vị phát hành dự kiến'}{internal?<select name="issuing_agency"><option value="">-- Chọn sau --</option>{INTERNAL_UNITS.map(x=><option key={x}>{x}</option>)}</select>:<input name="issuing_agency"/>}</label><label className="wide">Lý do xin số trước <span className="req">*</span><textarea name="reason" required/></label></div>{error&&<div className="form-error">{error}</div>}<div className="end"><button type="button" onClick={close}>Hủy</button><button className="primary" disabled={busy}>{busy?'Đang giữ số...':'Xin số'}</button></div></form></div>}
function AttachReservedDialog({action,call,close,done}){const d=action.document,[busy,setBusy]=useState(false),[error,setError]=useState('');async function submit(e){e.preventDefault();setBusy(true);setError('');try{await call(`/documents/${d.id}/attach-reserved`,{method:'POST',body:new FormData(e.currentTarget)});done()}catch(e){setError(e.message)}finally{setBusy(false)}}return <div className="modal action-modal"><form onSubmit={submit}><h2>Bổ sung văn bản cho số {d.symbol}</h2><div className="grid"><label className="wide">Trích yếu <span className="req">*</span><input name="title" defaultValue={d.title} required/></label><label>Ngày phát hành <span className="req">*</span><input name="issued_date" type="date" required/></label><label>{d.direction==='OUT'?'Đơn vị tiếp nhận':'Đơn vị phát hành'} <span className="req">*</span>{d.direction==='INTERNAL'?<select name="issuing_agency" defaultValue={d.issuing_agency||''} required><option value="">-- Chọn đơn vị --</option>{INTERNAL_UNITS.map(x=><option key={x}>{x}</option>)}</select>:<input name="issuing_agency" defaultValue={d.issuing_agency||''} required/>}</label><label className="wide">File PDF <span className="req">*</span><input name="file" type="file" accept=".pdf,application/pdf" required/></label></div><p>Số đã giữ nguyên và sẽ được ghép vào tên file sau khi tải lên.</p>{error&&<div className="form-error">{error}</div>}<div className="end"><button type="button" onClick={close}>Hủy</button><button className="primary" disabled={busy}>{busy?'Đang bổ sung...':'Bổ sung văn bản'}</button></div></form></div>}
function MultiPagePlacement({mode,action,call,token,close,done}){
 const[pages,setPages]=useState([]),[placement,setPlacement]=useState({page:1,x:55,y:68}),[sealType,setSealType]=useState('SCHOOL'),[dragging,setDragging]=useState(false),[busy,setBusy]=useState(false),[loading,setLoading]=useState(true),[error,setError]=useState('');
 useEffect(()=>{let urls=[],controller=new AbortController();async function load(){setLoading(true);setError('');try{let suffix=mode==='sign'?'?source=true':'';let metaRes=await fetch(`${API}/documents/${action.document.id}/preview-info${suffix}`,{headers:{Authorization:`Bearer ${token}`},signal:controller.signal});if(!metaRes.ok)throw Error('Không thể đọc thông tin PDF');let meta=await metaRes.json();if(mode==='sign'){let sig=await fetch(`${API}/documents/${action.document.id}/digital-signature`,{headers:{Authorization:`Bearer ${token}`},signal:controller.signal}).then(r=>r.ok?r.json():null);if(sig?.signed)setPlacement({page:sig.page,x:sig.x_percent,y:sig.y_percent})}let loaded=await Promise.all(meta.pages.map(async p=>{let r=await fetch(`${API}/documents/${action.document.id}/pages/${p.page}/preview${suffix}`,{headers:{Authorization:`Bearer ${token}`},signal:controller.signal});if(!r.ok)throw Error(`Không thể tải trang ${p.page}`);let url=URL.createObjectURL(await r.blob());urls.push(url);return{...p,url}}));setPages(loaded)}catch(e){if(e.name!=='AbortError')setError(e.message)}finally{setLoading(false)}}load();return()=>{controller.abort();urls.forEach(URL.revokeObjectURL)}},[mode,action.document.id,token]);
 function place(e,page){let r=e.currentTarget.getBoundingClientRect();setPlacement({page,x:Math.max(0,Math.min(100,(e.clientX-r.left)/r.width*100)),y:Math.max(0,Math.min(100,(e.clientY-r.top)/r.height*100))})}
 function start(e,page){e.preventDefault();setDragging(true);e.currentTarget.setPointerCapture(e.pointerId);place(e,page)}
 async function confirm(){setBusy(true);setError('');try{let f=new FormData();f.set('page',placement.page);f.set('x_percent',placement.x.toFixed(6));f.set('y_percent',placement.y.toFixed(6));if(mode==='seal')f.set('seal_type',sealType);await call(`/documents/${action.document.id}/${mode==='sign'?'digital-sign':'digital-seal'}`,{method:'POST',body:f});done()}catch(e){setError(e.message)}finally{setBusy(false)}}
 return <div className="modal signing-modal"><section className="signing-studio multi-page-studio"><header><div><h2>{mode==='sign'?'Ký số văn bản':'Đóng dấu văn bản'}</h2><p>{action.document.title}</p></div><button onClick={close} disabled={busy}>Đóng</button></header><div className="signing-toolbar">{mode==='seal'&&<label>Loại con dấu<select value={sealType} onChange={e=>setSealType(e.target.value)}><option value="SCHOOL">Dấu Trường</option><option value="OFFICE">Dấu Văn phòng</option></select></label>}<strong>Cuộn đến trang cần {mode==='sign'?'ký':'đóng dấu'}, sau đó nhấn hoặc kéo để đặt vị trí</strong><span>Trang {placement.page} · {Math.round(placement.x)}% × {Math.round(placement.y)}%</span></div><div className="pdf-scroll">{loading?<div className="pdf-placeholder"><FileText/><b>Đang tải toàn bộ PDF...</b></div>:pages.map(p=><div className="page-wrap" key={p.page}><small>Trang {p.page} / {pages.length}</small><div className="pdf-page" style={{aspectRatio:`${p.width}/${p.height}`}} onPointerDown={e=>start(e,p.page)} onPointerMove={e=>dragging&&place(e,p.page)} onPointerUp={()=>setDragging(false)} onPointerCancel={()=>setDragging(false)}><img src={p.url} alt={`Trang ${p.page}`}/>{placement.page===p.page&&(mode==='sign'?<div className="signature-ellipse" style={{left:`${placement.x}%`,top:`${placement.y}%`}}><b>ĐÃ KÝ SỐ</b><small>Đại học Hùng Vương</small></div>:<div className="seal-stamp" style={{left:`${placement.x}%`,top:`${placement.y}%`}}><span>{sealType==='SCHOOL'?'TRƯỜNG ĐẠI HỌC HÙNG VƯƠNG':'VĂN PHÒNG'}</span><b>GIẢ LẬP</b><small>TP. HỒ CHÍ MINH</small></div>)}</div></div>)}</div>{error&&<div className="form-error">{error}</div>}<footer><span>Vị trí được tính riêng theo trang, không phụ thuộc khoảng cuộn.</span><div className="end"><button onClick={close} disabled={busy}>Hủy</button><button className="primary" onClick={confirm} disabled={busy||loading||!pages.length}>{busy?'Đang xử lý...':mode==='sign'?'Xác nhận ký số':'Xác nhận đóng dấu'}</button></div></footer></section></div>
}
function PlacementStudio({mode,action,call,token,close,done}){
 const[url,setUrl]=useState(''),[pos,setPos]=useState({x:55,y:68}),[page,setPage]=useState(1),[sealType,setSealType]=useState('SCHOOL'),[dragging,setDragging]=useState(false),[busy,setBusy]=useState(false),[loading,setLoading]=useState(true),[error,setError]=useState('');
 useEffect(()=>{let objectUrl='',controller=new AbortController();setLoading(true);setError('');fetch(`${API}/documents/${action.document.id}/pages/${page}/preview${mode==='sign'?'?source=true':''}`,{headers:{Authorization:`Bearer ${token}`},signal:controller.signal}).then(async r=>{if(!r.ok)throw Error(r.status===404?'Trang PDF không tồn tại':'Không thể tải trang PDF');objectUrl=URL.createObjectURL(await r.blob());setUrl(objectUrl)}).catch(e=>{if(e.name!=='AbortError'){setUrl('');setError(e.message)}}).finally(()=>setLoading(false));return()=>{controller.abort();if(objectUrl)URL.revokeObjectURL(objectUrl)}},[action.document.id,page,token,mode]);
 useEffect(()=>{if(mode!=='sign')return;fetch(`${API}/documents/${action.document.id}/digital-signature`,{headers:{Authorization:`Bearer ${token}`}}).then(r=>r.ok?r.json():null).then(x=>{if(x?.signed){setPos({x:x.x_percent,y:x.y_percent});setPage(x.page)}})},[mode,action.document.id,token]);
 function place(e){let r=e.currentTarget.getBoundingClientRect();setPos({x:Math.max(0,Math.min(100,(e.clientX-r.left)/r.width*100)),y:Math.max(0,Math.min(100,(e.clientY-r.top)/r.height*100))})}function start(e){e.preventDefault();setDragging(true);e.currentTarget.setPointerCapture(e.pointerId);place(e)}function move(e){if(dragging)place(e)}
 async function confirm(){setBusy(true);setError('');try{let f=new FormData();f.set('page',page);f.set('x_percent',Math.round(pos.x));f.set('y_percent',Math.round(pos.y));if(mode==='seal')f.set('seal_type',sealType);await call(`/documents/${action.document.id}/${mode==='sign'?'digital-sign':'digital-seal'}`,{method:'POST',body:f});done()}catch(e){setError(e.message)}finally{setBusy(false)}}
 return <div className="modal signing-modal"><section className="signing-studio"><header><div><h2>{mode==='sign'?'Ký số văn bản':'Đóng dấu văn bản'}</h2><p>{action.document.title}</p></div><button onClick={close} disabled={busy}>Đóng</button></header><div className="signing-toolbar">{mode==='seal'&&<label>Loại con dấu<select value={sealType} onChange={e=>setSealType(e.target.value)}><option value="SCHOOL">Dấu Trường</option><option value="OFFICE">Dấu Văn phòng</option></select></label>}<label>Trang {mode==='sign'?'ký':'đóng dấu'}<input type="number" min="1" value={page} onChange={e=>setPage(Math.max(1,Number(e.target.value)||1))}/></label><span>Vị trí: {Math.round(pos.x)}% × {Math.round(pos.y)}%</span></div><div className="pdf-stage exact-preview" onPointerDown={start} onPointerMove={move} onPointerUp={()=>setDragging(false)} onPointerCancel={()=>setDragging(false)}>{loading?<div className="pdf-placeholder"><FileText/><b>Đang render trang PDF...</b></div>:url?<img src={url} alt={`Trang PDF ${page}`}/>:<div className="pdf-placeholder"><FileText/><b>Không thể hiển thị trang PDF</b></div>}{url&&!loading&&(mode==='sign'?<div className="signature-ellipse" style={{left:`${pos.x}%`,top:`${pos.y}%`}}><b>ĐÃ KÝ SỐ</b><small>Đại học Hùng Vương</small></div>:<div className="seal-stamp" style={{left:`${pos.x}%`,top:`${pos.y}%`}}><span>{sealType==='SCHOOL'?'TRƯỜNG ĐẠI HỌC HÙNG VƯƠNG':'VĂN PHÒNG'}</span><b>GIẢ LẬP</b><small>TP. HỒ CHÍ MINH</small></div>)}</div>{error&&<div className="form-error">{error}</div>}<footer><span>Nhấn hoặc kéo trực tiếp trên trang để đặt đúng vị trí.</span><div className="end"><button onClick={close} disabled={busy}>Hủy</button><button className="primary" onClick={confirm} disabled={busy||loading||!url}>{busy?'Đang xử lý...':mode==='sign'?'Xác nhận ký số':'Xác nhận đóng dấu'}</button></div></footer></section></div>
}
function InternalApprovalDialog({action,call,close,done}){const[busy,setBusy]=useState(false),[error,setError]=useState(''),approving=action.type==='INTERNAL_APPROVE';async function submit(e){e.preventDefault();setBusy(true);setError('');try{await call(`/documents/${action.document.id}/${approving?'internal-approve':'internal-submit'}`,{method:'POST',body:approving?new FormData(e.currentTarget):undefined});done()}catch(e){setError(e.message)}finally{setBusy(false)}}return <div className="modal action-modal" onMouseDown={e=>e.target===e.currentTarget&&!busy&&close()}><form onSubmit={submit}><h2>{approving?'Phê duyệt văn bản nội bộ':'Trình Trưởng Văn phòng phê duyệt'}</h2><p>{approving?'Xác nhận văn bản đủ điều kiện để chuyển sang bước đóng dấu và phát hành?':'Văn bản đã được cấp số. Xác nhận trình Trưởng Văn phòng xem xét, phê duyệt trước khi đóng dấu?'}</p>{approving&&<label>Ý kiến phê duyệt<textarea name="note" placeholder="Nhập ý kiến (không bắt buộc)" autoFocus/></label>}{error&&<div className="form-error">{error}</div>}<div className="end"><button type="button" onClick={close} disabled={busy}>Hủy</button><button className="primary" disabled={busy}>{busy?'Đang xử lý...':approving?'Xác nhận phê duyệt':'Xác nhận trình duyệt'}</button></div></form></div>}
function IncomingRowActions({d,act,permissions}){const[busy,setBusy]=useState(false),can=code=>permissions.includes(code);async function takeNumber(){if(busy)return;setBusy(true);try{let r=await fetch(`${API}/documents/${d.id}/incoming-number`,{method:'POST',headers:{Authorization:`Bearer ${localStorage.token}`},body:new FormData()}),j=await r.json();if(!r.ok)throw Error(j.detail||'Không thể lấy số');location.reload()}catch(e){alert(e.message);setBusy(false)}}async function attach(e){let file=e.target.files[0];if(!file)return;let f=new FormData();f.set('file',file);let r=await fetch(`${API}/documents/${d.id}/attach-reserved`,{method:'POST',headers:{Authorization:`Bearer ${localStorage.token}`},body:f});if(r.ok)location.reload();else alert((await r.json()).detail||'Không thể bổ sung văn bản')}let controls=d.status==='RESERVED_INCOMING'&&can('EDIT')?<label className="attach-button">Bổ sung PDF<input type="file" accept=".pdf,application/pdf" onChange={attach}/></label>:d.status==='RECEIVED'?(<>{can('EDIT')&&<button onClick={()=>act(d,'IN_EDIT')} disabled={busy}>Sửa</button>}{can('ASSIGN_NUMBER')&&<button onClick={takeNumber} disabled={busy}>{busy?'Đang lấy số...':'Lấy số'}</button>}</>):d.status==='NUMBERED'&&can('OFFICE_OPINION')?<button onClick={()=>act(d,'IN_OFFICE')}>Cho ý kiến VP</button>:d.status==='OFFICE_OPINION_COMPLETED'&&can('SEND_BGH')?<button onClick={()=>act(d,'IN_SEND_BGH')}>Gửi BGH</button>:d.status==='PENDING_BGH'&&can('BGH_DECIDE')?<button onClick={()=>act(d,'IN_BGH')}>BGH xử lý</button>:d.status==='BGH_APPROVED'&&can('FORWARD')?<button onClick={()=>act(d,'IN_FORWARD')}>Chuyển đơn vị</button>:d.status==='FORWARDED'&&can('ARCHIVE')?<button onClick={()=>act(d,'ARCHIVE')}>Lưu trữ + OCR</button>:null;return <>{controls}{can('DELETE')&&<button className="danger-link" onClick={()=>act(d,'DELETE')} disabled={busy}>Xóa</button>}</>}
function OutgoingRowActions({d,act,permissions}){const[busy,setBusy]=useState(false),can=code=>permissions.includes(code);async function takeNumber(){setBusy(true);try{let r=await fetch(`${API}/documents/${d.id}/outgoing-number`,{method:'POST',headers:{Authorization:`Bearer ${localStorage.token}`},body:new FormData()}),j=await r.json();if(!r.ok)throw Error(j.detail||'Không thể cấp số');location.reload()}catch(e){alert(e.message);setBusy(false)}}let controls=d.status==='RESERVED_OUTGOING'&&can('EDIT')?<button onClick={()=>act(d,'ATTACH_RESERVED')}>Bổ sung PDF</button>:['DRAFT','RETURNED'].includes(d.status)&&can('EDIT')?<><button onClick={()=>act(d,'OUT_EDIT')}>Sửa</button><button onClick={()=>act(d,'OUT_SUBMIT')}>{d.status==='RETURNED'?'Trình lại':'Trình Trưởng VP'}</button></>:d.status==='PENDING_OFFICE_SIGN'&&can('SIGN')?<><button onClick={()=>act(d,'PERSONAL_SIGN')}>Ký số</button><button onClick={()=>act(d,'OUT_RETURN')}>Trả lại</button></>:d.status==='OFFICE_SIGNED'&&can('ASSIGN_NUMBER')?<button onClick={takeNumber} disabled={busy}>{busy?'Đang cấp số...':'Cấp số'}</button>:d.status==='OUT_NUMBERED'&&can('SEAL')?<button onClick={()=>act(d,'SEAL_SIGN')}>Đóng dấu</button>:d.status==='SEALED'&&can('EMAIL')?<button onClick={()=>act(d,'OUT_EMAIL')}>Gửi mail</button>:d.status==='EMAILED'&&can('ARCHIVE')?<button onClick={()=>act(d,'ARCHIVE')}>Lưu trữ + OCR</button>:null;return <>{controls}{can('DELETE')&&<button className="danger-link" onClick={()=>act(d,'DELETE')} disabled={busy}>Xóa</button>}</>}
function InternalRowActions({d,act,permissions}){const[busy,setBusy]=useState(false),can=code=>permissions.includes(code);async function takeNumber(){setBusy(true);try{let r=await fetch(`${API}/documents/${d.id}/internal-number`,{method:'POST',headers:{Authorization:`Bearer ${localStorage.token}`}}),j=await r.json();if(!r.ok)throw Error(j.detail||'Không thể cấp số');location.reload()}catch(e){alert(e.message);setBusy(false)}}let controls=d.status==='RESERVED_INTERNAL'&&can('EDIT')?<button onClick={()=>act(d,'ATTACH_RESERVED')}>Bổ sung PDF</button>:d.status==='DRAFT'&&can('ASSIGN_NUMBER')?<button onClick={takeNumber} disabled={busy}>{busy?'Đang cấp số...':'Cấp số'}</button>:d.status==='INTERNAL_NUMBERED'&&can('EDIT')?<button onClick={()=>act(d,'INTERNAL_SUBMIT')}>Trình Trưởng VP</button>:d.status==='PENDING_INTERNAL_APPROVAL'&&can('INTERNAL_APPROVE')?<button onClick={()=>act(d,'INTERNAL_APPROVE')}>Phê duyệt</button>:d.status==='INTERNAL_APPROVED'&&can('SEAL')?<button onClick={()=>act(d,'SEAL_SIGN')}>Đóng dấu</button>:d.status==='INTERNAL_SEALED'&&can('EMAIL')?<button onClick={()=>act(d,'INTERNAL_EMAIL')}>Phát hành (mail)</button>:d.status==='INTERNAL_PUBLISHED'&&can('ARCHIVE')?<button onClick={()=>act(d,'ARCHIVE')}>Lưu trữ + OCR</button>:null;return <>{controls}{can('DELETE')&&<button className="danger-link" onClick={()=>act(d,'DELETE')}>Xóa</button>}</>}
function Table({rows,act,download,permissions=[]}){return <div className="table"><div className="tr head"><span>SỐ / KÝ HIỆU</span><span>TRÍCH YẾU</span><span>LOẠI</span><span>TRẠNG THÁI</span><span>THAO TÁC</span></div>{rows.map(d=><div className="tr" key={d.id}><span><b>{d.symbol||'Chưa cấp số'}</b><small>{d.direction==='IN'?'Văn bản đến':d.direction==='OUT'?'Văn bản đi':'Văn bản nội bộ'}</small></span><span>{d.title}<small>{d.issuing_agency}</small></span><span>{d.doc_type}</span><span><em>{d.status}</em></span><span className="actions">{act&&d.file_name&&<button onClick={()=>act(d,'VIEW')}>Xem</button>}{act&&(d.direction==='IN'?<IncomingRowActions d={d} act={act} permissions={permissions}/>:d.direction==='OUT'?<OutgoingRowActions d={d} act={act} permissions={permissions}/>:<InternalRowActions d={d} act={act} permissions={permissions}/>)}{download&&d.file_name&&<button onClick={()=>download(d)}>Tải PDF</button>}</span></div>)}{!rows.length&&<div className="empty">Chưa có văn bản phù hợp</div>}</div>}
function Create({direction,deps,token,close,saved}){const[saving,setSaving]=useState(false),office=deps.find(x=>x.code==='VP'||x.name.toLowerCase().includes('văn phòng')),internal=direction==='INTERNAL';async function go(e){e.preventDefault();setSaving(true);try{let f=new FormData(e.target);f.set('direction',direction);if(!internal)f.set('doc_type','CÔNG VĂN');if(office)f.set('department_id',office.id);let r=await fetch(API+'/documents',{method:'POST',headers:{Authorization:`Bearer ${token}`},body:f});let j=await r.json().catch(()=>({detail:'Máy chủ trả về dữ liệu không hợp lệ'}));if(!r.ok)throw Error(j.detail||`Không thể lưu văn bản (${r.status})`);saved(j)}catch(err){alert(`Lưu văn bản thất bại: ${err.message}`)}finally{setSaving(false)}}return <div className="modal"><form onSubmit={go}><h2>{direction==='IN'?'Tiếp nhận công văn đến':direction==='OUT'?'Tạo công văn đi':'Tạo công văn nội bộ'}</h2><div className="grid"><label>Loại văn bản <span className="req">*</span>{internal?<select name="doc_type" required><option value="">-- Chọn loại --</option><option>QUYẾT ĐỊNH</option><option>KẾ HOẠCH</option><option>THÔNG BÁO</option></select>:<input value={direction==='IN'?'CÔNG VĂN ĐẾN':'CÔNG VĂN ĐI'} disabled/>}</label><label>{internal?'Ngày phát hành':'Ngày ban hành'} <span className="req">*</span><input type="date" name="issued_date" required/></label><label className="wide">Trích yếu <span className="req">*</span><input name="title" required/></label><label>{internal?'Đơn vị phát hành':direction==='IN'?'Đơn vị ban hành':'Đơn vị tiếp nhận'} <span className="req">*</span>{internal?<select name="issuing_agency" required><option value="">-- Chọn đơn vị --</option>{INTERNAL_UNITS.map(x=><option key={x}>{x}</option>)}</select>:<input name="issuing_agency" required/>}</label><label>Đơn vị xử lý <span className="req">*</span><input value="Văn phòng Trường" disabled/><input type="hidden" name="department_id" value={office?.id||''}/></label><label className="wide">Tóm tắt <small>(không bắt buộc)</small><textarea name="summary"/></label><label className="wide">File PDF <span className="req">*</span><input type="file" name="file" accept=".pdf,application/pdf" required/></label></div><div className="end"><button type="button" onClick={close} disabled={saving}>Hủy</button><button className="primary" disabled={saving}>{saving?'Đang lưu...':'Lưu văn bản'}</button></div></form></div>}
function PermissionEditor({roles,onMessage}){const[values,setValues]=useState({});useEffect(()=>setValues(Object.fromEntries((roles||[]).map(r=>[r.code,(r.permission_options||[]).filter(p=>p.enabled).map(p=>p.code)]))),[roles]);async function save(role){let r=await fetch(API+'/config/permissions',{method:'PUT',headers:{Authorization:`Bearer ${localStorage.token}`,'Content-Type':'application/json'},body:JSON.stringify({role:role.code,permissions:values[role.code]||[]})}),j=await r.json().catch(()=>({}));onMessage(r.ok?`Đã lưu phân quyền ${role.name}`:j.detail||'Không thể lưu phân quyền')}function toggle(role,code){setValues(v=>({...v,[role]:v[role]?.includes(code)?v[role].filter(x=>x!==code):[...(v[role]||[]),code]}))}return <div className="permission-editor">{(roles||[]).map(role=><article key={role.code}><header><div><b>{role.name}</b><small>{role.code}</small></div><button onClick={()=>save(role)} disabled={role.code==='ADMIN'}>{role.code==='ADMIN'?'Đã khóa':'Lưu quyền'}</button></header><div>{(role.permission_options||[]).map(p=><label key={p.code}><input type="checkbox" checked={(values[role.code]||[]).includes(p.code)} disabled={role.code==='ADMIN'} onChange={()=>toggle(role.code,p.code)}/><span>{p.name}</span></label>)}</div></article>)}</div>}
function Config({c}){const[activity,setActivity]=useState([]),[message,setMessage]=useState(''),headers={Authorization:`Bearer ${localStorage.token}`,'Content-Type':'application/json'};useEffect(()=>{fetch(API+'/activity',{headers:{Authorization:`Bearer ${localStorage.token}`}}).then(r=>r.ok?r.json():[]).then(setActivity)},[]);async function saveUser(e,user){e.preventDefault();let body=Object.fromEntries(new FormData(e.currentTarget));body.department_id=body.department_id?Number(body.department_id):null;body.active=body.active==='on';let r=await fetch(`${API}/config/users/${user.id}`,{method:'PUT',headers,body:JSON.stringify(body)});setMessage(r.ok?'Đã cập nhật người dùng':(await r.json()).detail)}async function saveEmail(e){e.preventDefault();let body=Object.fromEntries(new FormData(e.currentTarget));if(!htmlHasContent(body.signature_html)){setMessage('Chữ ký email là bắt buộc');return}body.smtp_port=Number(body.smtp_port);body.use_tls=body.use_tls==='on';body.enabled=body.enabled==='on';let r=await fetch(API+'/config/email',{method:'PUT',headers,body:JSON.stringify(body)});setMessage(r.ok?'Đã lưu cấu hình email':(await r.json()).detail)}return <div className="config-page">{message&&<div className="config-message">{message}</div>}<section className="panel"><h3>Người dùng và vai trò</h3><p>Quản lý vai trò, đơn vị và trạng thái sử dụng của từng tài khoản.</p><div className="config-users">{(c.users||[]).map(user=>{const locked=user.username==='admin';return <form key={user.id} className={locked?'is-locked':''} onSubmit={e=>saveUser(e,user)}><div><b>{user.username}</b><input name="full_name" defaultValue={user.full_name} required disabled={locked}/></div><select name="role" defaultValue={user.role} disabled={locked}>{(c.roles||[]).map(r=><option key={r.code} value={r.code}>{r.name}</option>)}</select><select name="department_id" defaultValue={user.department_id||''} disabled={locked}><option value="">Không gán đơn vị</option>{c.departments.map(d=><option key={d.id} value={d.id}>{d.name}</option>)}</select><label className="check"><input name="active" type="checkbox" defaultChecked={user.active} disabled={locked}/> Hoạt động</label><button disabled={locked}>Lưu</button></form>})}</div></section><section className="panel"><h3>Phân quyền theo vai trò</h3><p>Bật hoặc tắt quyền có hiệu lực trực tiếp trên API. Quyền Admin được khóa để tránh mất quyền quản trị.</p><PermissionEditor roles={c.roles||[]} onMessage={setMessage}/></section><section className="panel"><h3>Cấu hình email</h3><form className="email-config" onSubmit={saveEmail}><label>SMTP host<input name="smtp_host" defaultValue={c.email?.smtp_host||''}/></label><label>Cổng SMTP<input name="smtp_port" type="number" defaultValue={c.email?.smtp_port||587}/></label><label>Tài khoản SMTP<input name="username" defaultValue={c.email?.username||''}/></label><label>Tên người gửi<input name="sender_name" defaultValue={c.email?.sender_name||''}/></label><label>Email người gửi<input name="sender_email" type="email" defaultValue={c.email?.sender_email||''}/></label><SignatureConfig initial={c.email?.signature_html||''}/><label className="check"><input name="use_tls" type="checkbox" defaultChecked={c.email?.use_tls!==false}/> Sử dụng TLS</label><label className="check"><input name="enabled" type="checkbox" defaultChecked={c.email?.enabled}/> Bật gửi email</label><button className="primary">Lưu cấu hình email</button></form></section><section className="panel"><h3>Activity log</h3><div className="activity-table"><div className="activity-head"><b>THỜI GIAN</b><b>NGƯỜI THỰC HIỆN</b><b>THAO TÁC</b><b>VĂN BẢN</b><b>CHI TIẾT</b></div>{activity.map(x=><div key={x.id}><time>{new Date(x.created_at).toLocaleString('vi-VN')}</time><span><b>{x.full_name}</b><small>{x.username} · {x.role}</small></span><code>{ACTION_LABELS[x.action]||x.action}</code><span><b>{x.symbol||'Chưa cấp số'}</b><small>{x.title}</small></span><span>{x.comment||'—'}</span></div>)}</div></section></div>};createRoot(document.getElementById('root')).render(<App/>);
